#!/usr/bin/env node
/**
 * Material nachtragen (Besitzer 27.10.2026: «Material zur Auswahl … und alle anderen auch nachtragen»).
 *
 * Schreibt das Metafeld `mm-google-shopping.material` (single_line_text_field) bei jedem aktiven Produkt, das noch kein Material zeigt
 * UND dessen Material in einer belegten Quelle steht (lib/material.mjs: Produkttext «Material: …» oder CJ-Datenblatt). Der Theme-Block
 * `lux_spezifikationen` zeigt das Feld als Zeile «Material» in «Spezifikationen & Details»; dasselbe Feld füttert das Merchant-Center-Attribut.
 * Nichts wird erfunden: ohne Quelle bleibt das Produkt leer (siehe Zusammenfassung «keine-quelle»).
 *
 * TROCKENLAUF IST VORGABE. LIVE=1 schreibt (25 Produkte je Aufruf) und liest jeden bestätigten Stapel vor dem nächsten FRISCH zurück.
 * Abgelehnte oder unklare Schreibvorgänge stoppen den Lauf (Exit 1), abweichende Rücklesungen ebenfalls (Exit 3). Kein automatischer Schreib-Retry.
 * Vor jedem Stapel: Wert und Typ frisch gegen den Plan prüfen; compareDigest schützt anschliessende parallele Änderungen.
 * LIVE verlangt den Antwortheader der dokumentiert unterstützten API-Version 2026-10. Ein Versions-Fallback bleibt gesperrt.
 * Bulk-Start ebenfalls ohne Schreib-Retry; danach nur die bestätigte eigene Operations-ID lesen.
 * Aufruf:  node automation/material_nachtragen.mjs                       (Trockenlauf, eigener Plan je Lauf in /tmp)
 *          LIVE=1 node automation/material_nachtragen.mjs                (schreiben)
 * Umgebung: PLAN=pfad · ROH=pfad (vorhandene Bulk-Datei statt neuer Abfrage) · ROH_AUS=pfad (Bulk-Rohdaten speichern) · CJ_FAKTEN_CACHE=ordner (Vorgabe /tmp/cj_fakten_cache)
 *           LIMIT=n (höchstens n Schreibvorgänge) · ONLY=handle,handle
 * LIVE benötigt zusätzlich MATERIAL_WRITE_LEDGER (vorhandener dauerhafter Belegpfad) und MATERIAL_WRITE_EVIDENCE (geprüfte Quellen/Altersregel).
 * Keine automatische Ledger-Initialisierung oder Quellenfrist. Der Trockenplan nennt ohne Beleg nur den Eingabehash, keine erfundene Prüfzeit.
 * Ein bestehender PLAN bleibt unverändert: nur bytegleiche Pläne sind wiederverwendbar. Für einen neuen Restplan einen neuen Pfad wählen.
 * Der Plan enthält geplante Änderungen, keinen Beleg erfolgreich geschriebener Werte.
 */
import { readFileSync, writeFileSync, existsSync, appendFileSync } from 'node:fs';
import { randomUUID, createHash } from 'node:crypto';
import { shopifyGql } from './lib/shopify_gql.mjs';
import { shopifyClientSecret } from './lib/shopify_secret.mjs';
import { entscheide, hatMaterial, enZuDe, bereinige, pruefeWert, lederWert } from './lib/material.mjs';
import { beginMaterialBatch, finishMaterialBatch } from './lib/material_write_ledger.mjs';

const LIVE = process.env.LIVE === '1';
const API_VERSION = '2026-10';
const PLAN = process.env.PLAN || `/tmp/material_plan_${new Date().toISOString().replace(/[:.]/g, '-')}_${randomUUID()}.jsonl`;
const ROH = process.env.ROH || '';
const CJ_ORDNER = (process.env.CJ_FAKTEN_CACHE || '/tmp/cj_fakten_cache').replace(/\/?$/, '/');
const LIMIT = Number(process.env.LIMIT || 1e9);
const ONLY = new Set((process.env.ONLY || '').split(',').map(s => s.trim()).filter(Boolean));
const BELEGE_TEXT = existsSync('dropship/material_belege.json') ? readFileSync('dropship/material_belege.json', 'utf8') : null;
const BELEGE = BELEGE_TEXT === null ? {} : JSON.parse(BELEGE_TEXT);
const EVIDENZ = process.env.MATERIAL_WRITE_EVIDENCE ? JSON.parse(readFileSync(process.env.MATERIAL_WRITE_EVIDENCE, 'utf8')) : null;
const LEDGER = process.env.MATERIAL_WRITE_LEDGER;
const sha256 = b => createHash('sha256').update(b).digest('hex');
const schlaf = ms => new Promise(r => setTimeout(r, ms));

function bestaetigterShop(shop) {
  const url = new URL(shop?.url);
  if (url.protocol !== 'https:' || url.host !== 'luxestyle.ch' || url.username || url.password || url.pathname !== '/' || url.search || url.hash || shop?.currencyCode !== 'CHF') throw new Error('Frische Shop-Identität oder CHF nicht bestätigt');
  return url.hostname;
}

// Exklusiv anlegen: auch ein gleichzeitiger Lauf darf keinen früheren Plan ersetzen.
function sicherePlan(datei, inhalt) {
  try { writeFileSync(datei, inhalt, { flag: 'wx' }); }
  catch (e) {
    if (e.code !== 'EEXIST') throw e;
    if (readFileSync(datei, 'utf8') !== inhalt) throw new Error('Plandatei bleibt unverändert: ' + datei + '. Für den neuen Plan einen neuen PLAN-Pfad wählen.');
  }
}

function sichereVorwerte(stueck, nodes) {
  const r = { m: [], konflikte: 0, unbekannt: 0 };
  const ids = new Set(stueck.map(p => p.id));
  if (ids.size !== stueck.length || !Array.isArray(nodes) || nodes.length !== stueck.length ||
      nodes.some(n => !n || !ids.has(n.id)) || new Set(nodes.map(n => n.id)).size !== stueck.length) {
    return { ...r, unbekannt: stueck.length };
  }
  const frisch = new Map(nodes.map(n => [n.id, n]));
  for (const p of stueck) {
    const n = frisch.get(p.id), alt = p.vorher;
    if (typeof n.status !== 'string') { r.unbekannt++; continue; }
    if (n.status !== 'ACTIVE') { r.konflikte++; continue; }
    if (!Object.hasOwn(n, 'm') || (alt !== null && (!alt || typeof alt.value !== 'string' || typeof alt.type !== 'string'))) { r.unbekannt++; continue; }
    if (alt !== null && alt.type !== 'single_line_text_field') { r.konflikte++; continue; }
    let compareDigest;
    if (n.m === null) {
      if (alt !== null) { r.konflikte++; continue; }
      compareDigest = null; // Explizites null bedeutet: nur anlegen, solange das Feld fehlt.
    } else {
      if (!n.m || typeof n.m.value !== 'string' || typeof n.m.type !== 'string') { r.unbekannt++; continue; }
      if (alt === null || n.m.value !== alt.value || n.m.type !== alt.type) { r.konflikte++; continue; }
      if (typeof n.m.compareDigest !== 'string' || !n.m.compareDigest.trim()) { r.unbekannt++; continue; }
      compareDigest = n.m.compareDigest;
    }
    r.m.push({ ownerId: p.id, namespace: 'mm-google-shopping', key: 'material', type: 'single_line_text_field', value: p.wert, compareDigest });
  }
  return r;
}

async function main() {
  const SHOP = process.env.SHOPIFY_SHOP, CS = shopifyClientSecret(process.env.SHOPIFY_CLIENT_SECRET);
  const r = await fetch(`https://${SHOP}/admin/oauth/access_token`, { method: 'POST', headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ client_id: process.env.SHOPIFY_CLIENT_ID, client_secret: CS, grant_type: 'client_credentials' }) });
  const tok = (await r.json()).access_token; if (!tok) throw new Error('Kein Shopify-Token');
  const fetchMitVersion = async (...args) => {
    const antwort = await fetch(...args);
    if (antwort.status >= 200 && antwort.status < 300 && antwort.headers?.get?.('X-Shopify-API-Version') !== API_VERSION) {
      throw new Error('API-Version nicht bestätigt: erwartet ' + API_VERSION + ', erhalten ' + (antwort.headers?.get?.('X-Shopify-API-Version') || 'unbekannt'));
    }
    return antwort;
  };
  const q = (a, b, opt) => shopifyGql(SHOP, API_VERSION, tok, a, b, { ...opt, fetch: fetchMitVersion });
  const pruefeVersion = async () => bestaetigterShop((await q('query MaterialApiVersion { shop{url currencyCode} }', undefined, { versuche: 1 }))?.shop);

  let text;
  if (ROH && existsSync(ROH)) text = readFileSync(ROH, 'utf8');
  else {
    await pruefeVersion(); // Auch ein Bulk-Start im Trockenlauf verlangt die richtige Marke und Version.
    const lauf = (await q(`{currentBulkOperation(type:QUERY){status}}`)).currentBulkOperation;
    if (lauf && ['CREATED', 'RUNNING'].includes(lauf.status)) throw new Error('Es läuft schon eine Bulk-Abfrage — abwarten');
    const inner = `{ products(query:"status:active") { edges { node { id handle title descriptionHtml options{ name } m:metafield(namespace:"mm-google-shopping", key:"material"){ value type } } } } }`;
    let m;
    try { m = (await q(`mutation($q:String!){bulkOperationRunQuery(query:$q){bulkOperation{id} userErrors{message}}}`, { q: inner }, { versuche: 1 }))?.bulkOperationRunQuery; }
    catch (e) { throw new Error('UNBEKANNT: Bulk-Start ohne bestätigte Antwort; nicht erneut starten. ' + e.message); }
    if (!m || !Array.isArray(m.userErrors)) throw new Error('UNBEKANNT: Bulk-Start unvollständig bestätigt; nicht erneut starten.');
    if (m.userErrors.length) throw new Error('Bulk-Start abgelehnt: ' + JSON.stringify(m.userErrors));
    const bulkId = m.bulkOperation?.id;
    if (typeof bulkId !== 'string' || !bulkId.trim()) throw new Error('UNBEKANNT: Bulk-Start ohne Operations-ID; nicht erneut starten.');
    for (let i = 0; i < 360; i++) {
      await schlaf(10000);
      // Seit API 2026-01 sind parallele Bulk-Queries möglich. Nicht den jüngsten fremden Job übernehmen.
      const s = (await q(`query($id:ID!){bulkOperation(id:$id){id status errorCode objectCount url}}`, { id: bulkId }))?.bulkOperation;
      if (!s || s.id !== bulkId || typeof s.status !== 'string') throw new Error('UNBEKANNT: eigene Bulk-Operation nicht bestätigt');
      if (s.status === 'COMPLETED') {
        if (typeof s.url !== 'string' || !s.url) throw new Error('UNBEKANNT: fertige Bulk-Operation ohne Ergebnis-URL');
        text = await (await fetch(s.url)).text(); break;
      }
      if (['FAILED', 'CANCELED', 'EXPIRED'].includes(s.status)) throw new Error('Bulk ' + s.status + ' ' + s.errorCode);
    }
    if (!text) throw new Error('Bulk-Abfrage dauert zu lange');
  }

  if (process.env.ROH_AUS) writeFileSync(process.env.ROH_AUS, text);   // Rohdaten für weitere Trockenläufe ohne neue Bulk-Abfrage (ROH=…)
  const z = { gelesen: 0 }, gruende = {}, werte = {}, plan = [], unbekannt = {}, quellbytes = new Map();
  for (const l of text.split('\n').filter(Boolean)) {
    const o = JSON.parse(l); if (!o.handle) continue;
    if (ONLY.size && !ONLY.has(o.handle)) continue;
    z.gelesen++;
    // Fehlende Rohfelder sind unbekannt; nur ein ausdrückliches m:null belegt Abwesenheit.
    const vorher = o.m === null ? null : { value: o.m?.value ?? null, type: o.m?.type ?? null };
    const datei = CJ_ORDNER + o.handle + '.json';
    const cjText = existsSync(datei) ? readFileSync(datei, 'utf8') : null;
    const cj = cjText === null ? null : JSON.parse(cjText);
    quellbytes.set(o.id, JSON.stringify({productJsonl:l,cjJson:cjText,manualEvidenceJson:BELEGE[o.handle] ? BELEGE_TEXT : null}));
    // Schon ein Metafeld: nur englische Werte («Silver», «Alloy», «Cotton») ins Deutsche setzen; deutsche bleiben unberührt
    const vorhanden = String(o.m?.value || '').trim();
    if (vorhanden) {
      const cjL = cj;
      // «Leather» (CJ-Grobfeld) nur mit Beleg übersetzen; ohne Beleg bleibt der Wert, wie er ist
      const de = /^leather$/i.test(vorhanden) ? lederWert({ titel: o.title, descriptionHtml: o.descriptionHtml, cj: cjL }) : enZuDe(vorhanden);
      if (/^leather$/i.test(vorhanden) && !de) gruende['leder-ohne-beleg'] = (gruende['leder-ohne-beleg'] || 0) + 1;
      if (de && de.toLowerCase() !== vorhanden.toLowerCase()) {
        const sperre = pruefeWert(de, { descriptionHtml: o.descriptionHtml, titel: o.title, cj: cjL }, { uebersetzung: true });
        if (sperre) gruende['sperre-uebersetzung'] = (gruende['sperre-uebersetzung'] || 0) + 1;
        else { plan.push({ id: o.id, handle: o.handle, wert: de, alt: vorhanden, quelle: 'uebersetzt', vorher }); werte[de] = (werte[de] || 0) + 1; }
      } else if (!de && !bereinige(vorhanden)) unbekannt[vorhanden] = (unbekannt[vorhanden] || 0) + 1;
      if (!(de && de.toLowerCase() !== vorhanden.toLowerCase())) gruende['schon-da:metafeld'] = (gruende['schon-da:metafeld'] || 0) + 1;
      continue;
    }
    let e = entscheide({ descriptionHtml: o.descriptionHtml, optionen: o.options, metafeld: o.m?.value, cj, titel: o.title });
    // Von Hand belegte Angaben (dropship/material_belege.json) gelten, wenn die Seite sonst noch kein Material zeigt
    if (!e.tun && BELEGE[o.handle]?.wert && !hatMaterial({ descriptionHtml: o.descriptionHtml, optionen: o.options, metafeld: o.m?.value })) {
      const wert = bereinige(BELEGE[o.handle].wert);
      const sperre = wert ? pruefeWert(wert, { descriptionHtml: o.descriptionHtml, titel: o.title, cj }) : 'kein sicherer Stoffname';
      e = sperre ? { tun: false, grund: 'sperre-beleg:' + sperre } : { tun: true, wert, quelle: 'belegt-von-hand' };
    }
    if (e.tun) { plan.push({ id: o.id, handle: o.handle, wert: e.wert, quelle: e.quelle, vorher }); werte[e.wert] = (werte[e.wert] || 0) + 1; }
    else { const g = e.grund.split(':').slice(0, 2).join(':').slice(0, 40); gruende[g.startsWith('schon') ? g : g.split(':')[0]] = (gruende[g.startsWith('schon') ? g : g.split(':')[0]] || 0) + 1; }
  }
  if (EVIDENZ && (!Array.isArray(EVIDENZ.sources) || new Set(EVIDENZ.sources.map(e => e.ownerId)).size !== EVIDENZ.sources.length)) throw new Error('Quellenbelege fehlen oder enthalten doppelte Produkt-IDs');
  for (const p of plan) {
    const e = EVIDENZ?.sources.find(e => e.ownerId === p.id), hash = sha256(quellbytes.get(p.id));
    if (e && e.sha256 !== hash) throw new Error('Quellenbeleg passt nicht zu den tatsächlich benutzten Eingaben: ' + p.handle);
    p.sourceEvidence = {ownerId:p.id,sha256:hash,reference:e?.reference ?? null,checkedAt:e?.checkedAt ?? null};
  }
  sicherePlan(PLAN, plan.map(p => JSON.stringify(p)).join('\n') + (plan.length ? '\n' : ''));
  const planBytes = readFileSync(PLAN);
  const quellen = plan.reduce((a, p) => (a[p.quelle] = (a[p.quelle] || 0) + 1, a), {});
  console.log(JSON.stringify({ ...z, zuSchreiben: plan.length, quellen, ohneEintrag: gruende, verschiedeneWerte: Object.keys(werte).length, plan: PLAN }));
  console.log('bestehende Metafeld-Werte, die weder deutsch noch übersetzbar sind (' + Object.keys(unbekannt).length + '):', Object.entries(unbekannt).sort((x, y) => y[1] - x[1]).slice(0, 40).map(([w, n]) => `${w}×${n}`).join(' | '));
  console.log('häufigste Werte:', Object.entries(werte).sort((a, b) => b[1] - a[1]).slice(0, 25).map(([w, n]) => `${w}×${n}`).join(' | '));
  if (!LIVE) { console.log('Trockenlauf — nichts geschrieben. LIVE=1 zum Schreiben.'); return; }
  await pruefeVersion(); // Reine Abfrage: Fallback oder fehlender Versionsheader sperrt vor Produktmutationen.

  const MUT = `mutation($m:[MetafieldsSetInput!]!){ metafieldsSet(metafields:$m){ metafields{ key } userErrors{ field message code } } }`;
  const VORHER = `query MaterialVorher($ids:[ID!]!){shop{url currencyCode} nodes(ids:$ids){... on Product{id status m:metafield(namespace:"mm-google-shopping",key:"material"){value type compareDigest}}}}`;
  const arbeit = plan.slice(0, LIMIT); const geschrieben = [];
  const runId = randomUUID();
  let angefragt = 0, apiBestaetigt = 0, fehler = 0, unklar = 0, rueckgelesen = 0, abweichungen = 0, vorherKonflikte = 0, vorherUnbekannt = 0, ledgerBlockiert = 0, ledgerFehler = 0;
  for (let i = 0; i < arbeit.length; i += 25) {
    const stueck = arbeit.slice(i, i + 25);
    let v, shopDomain;
    try {
      const d = await q(VORHER, { ids: stueck.map(p => p.id) }, { versuche: 1 });
      shopDomain = bestaetigterShop(d?.shop);
      v = sichereVorwerte(stueck, d?.nodes);
    }
    catch (e) { vorherUnbekannt += stueck.length; console.error('UNBEKANNT: Vorher-Gegenprobe fehlgeschlagen; nichts aus diesem Stapel gesendet.', e.message); break; }
    vorherKonflikte += v.konflikte; vorherUnbekannt += v.unbekannt;
    if (v.konflikte || v.unbekannt) { console.error('Vorher-Gegenprobe blockiert den ganzen Stapel:', JSON.stringify({ konflikte: v.konflikte, unbekannt: v.unbekannt })); break; }
    let claim;
    try {
      claim = beginMaterialBatch({ledgerPath:LEDGER,shopDomain,planBytes,batch:stueck,runId,
        sourceEvidence:stueck.map(p => ({...p.sourceEvidence,bytes:quellbytes.get(p.id)})),sourceAgePolicy:EVIDENZ?.sourceAgePolicy});
    } catch (e) { vorherUnbekannt += stueck.length; console.error('SCHREIBSPERRE: Ledger oder Quellenbeleg nicht bestätigt.', e.message); break; }
    if (claim.decision !== 'claimed_once') { ledgerBlockiert += stueck.length; console.error('SCHREIBSPERRE: bestehender Produktbeleg, kein erneutes Senden.', claim.entry?.state || 'unbekannt'); break; }
    const checkpoint = (state, details) => {
      try { finishMaterialBatch({ledgerPath:LEDGER,key:claim.key,claimToken:claim.entry.claimToken,expectedRevision:claim.entry.revision,state,...details}); return true; }
      catch (e) { ledgerFehler += stueck.length; console.error('UNBEKANNT: Ledger-Abschluss nicht bestätigt; kein erneutes Senden.', e.message); return false; }
    };
    angefragt += stueck.length;
    let w;
    try {
      // Die Antwort kann nach einer bereits ausgeführten Mutation verloren gehen. Nicht blind erneut senden.
      w = (await q(MUT, { m: v.m }, { versuche: 1 }))?.metafieldsSet;
    } catch (e) { unklar += stueck.length; checkpoint('unknown',{reason:'Schreibantwort fehlt: '+e.message}); console.error('UNBEKANNT: Schreibantwort fehlt; keine Wiederholung.', e.message); break; }
    if (!w || !Array.isArray(w.userErrors)) { unklar += stueck.length; checkpoint('unknown',{reason:'Unvollständige Schreibantwort'}); console.error('UNBEKANNT: unvollständige Schreibantwort; Abbruch.'); break; }
    // metafieldsSet ist atomar: Ein userError verwirft den ganzen Stapel, nicht nur den genannten Index.
    if (w.userErrors.length) { fehler += stueck.length; checkpoint('rejected',{userErrors:w.userErrors}); console.error('Stapel vollständig abgelehnt:', JSON.stringify(w.userErrors).slice(0, 300)); break; }
    if (!Array.isArray(w.metafields) || w.metafields.length !== stueck.length || w.metafields.some(m => m?.key !== 'material')) {
      unklar += stueck.length; checkpoint('unknown',{reason:'Metafelder nicht vollständig bestätigt'}); console.error('UNBEKANNT: gesetzte Metafelder nicht vollständig bestätigt; Abbruch.'); break;
    }
    apiBestaetigt += stueck.length;
    const readbacks = [];
    // Alle IDs dieses Stapels prüfen, auch wenn eine Rücklesung fehlschlägt. Erst dann weitere Mutationen erlauben.
    for (const p of stueck) {
      try {
        const d = await q(`query($id:ID!){product(id:$id){m:metafield(namespace:"mm-google-shopping", key:"material"){value type}}}`, { id: p.id });
        if (d?.product?.m !== null && (typeof d?.product?.m?.value !== 'string' || typeof d?.product?.m?.type !== 'string')) { unklar++; console.error('UNBEKANNT: Rücklesedaten fehlen', p.handle); continue; }
        rueckgelesen++;
        if (d.product.m?.value !== p.wert || d.product.m?.type !== 'single_line_text_field') { abweichungen++; console.error('ABWEICHUNG', p.handle, JSON.stringify(d.product.m), 'statt', JSON.stringify({value:p.wert,type:'single_line_text_field'})); }
        else { geschrieben.push(p); readbacks.push({ownerId:p.id,value:d.product.m.value,type:d.product.m.type,checkedAt:new Date().toISOString()}); }
      } catch (e) { unklar++; console.error('UNBEKANNT: Rücklesen fehlgeschlagen', p.handle, e.message); }
    }
    checkpoint(unklar ? 'unknown' : abweichungen ? 'conflict' : 'confirmed', unklar || abweichungen ? {reason:'Nachher-Gegenprobe nicht vollständig passend'} : {readbacks});
    if (unklar || abweichungen || ledgerFehler) { console.error('Gegenprobe nicht vollständig bestätigt — keine weiteren Mutationen.'); break; }
    if ((i / 25) % 20 === 19) console.log(`  … ${geschrieben.length} frisch bestätigt`);
    await schlaf(250);
  }
  const quellenBestaetigt = geschrieben.reduce((a, p) => (a[p.quelle] = (a[p.quelle] || 0) + 1, a), {});
  appendFileSync('dropship/material_ledger.txt', `${new Date().toISOString()} · material nachgetragen · ${geschrieben.length} Produkte (Fehler ${fehler}) · Unbekannt ${unklar} · Abweichungen ${abweichungen} · Vorher-Konflikte ${vorherKonflikte} · Vorher-unbekannt ${vorherUnbekannt} · Quellen ${JSON.stringify(quellenBestaetigt)}\n`);
  console.log(JSON.stringify({ geschrieben: geschrieben.length, apiBestaetigt, fehler, unbekannt: unklar, rueckgelesen, abweichungen, vorherKonflikte, vorherUnbekannt, ledgerBlockiert, ledgerFehler, nichtBearbeitet: arbeit.length - angefragt }));
  if (abweichungen) process.exitCode = 3;
  else if (fehler || unklar || vorherKonflikte || vorherUnbekannt || ledgerBlockiert || ledgerFehler) process.exitCode = 1;
}
main().catch(e => { console.error('FEHLER', e.message); process.exit(1); });

#!/usr/bin/env node
// Ausschliesslich lokale Attrappen: keine echten Shopify-/CJ-Zugriffe oder Zugangsdaten.
import assert from 'node:assert/strict';
import {materialFixtureBelege} from './lib/material_test_fixture.mjs';
import { mkdtempSync, mkdirSync, readFileSync, writeFileSync, copyFileSync, existsSync, rmSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { dirname, isAbsolute, join, relative, resolve, sep } from 'node:path';
import { fileURLToPath } from 'node:url';
import { spawnSync } from 'node:child_process';

const hier = dirname(fileURLToPath(import.meta.url));
const quelle = resolve(process.argv[2] || join(hier, 'material_nachtragen.mjs'));
const material = resolve(process.argv[3] || join(dirname(quelle), 'lib/material.mjs'));
const testOrdner = process.env.MATERIAL_TEST_TMP || tmpdir();
let ok = 0, fehler = 0;
const becher = { id: 'gid://shopify/Product/1001', handle: 'becher-fixture', title: 'Becher', descriptionHtml: '', options: [], m: { value: 'Ceramic', type: 'single_line_text_field' } };
const tasse = { ...becher, id: 'gid://shopify/Product/1002', handle: 'tasse-fixture' };
const leer = { id: 'gid://shopify/Product/1003', handle: 'leer-fixture', title: 'Muster', descriptionHtml: '', options: [], m: null };

function fixture(produkte = [becher]) {
  mkdirSync(testOrdner, {recursive:true});
  const dir = mkdtempSync(join(testOrdner, 'material-plan-test-'));
  mkdirSync(join(dir, 'automation/lib'), { recursive: true });
  mkdirSync(join(dir, 'dropship'));
