  writeFileSync(join(dir, 'automation/lib/shopify_gql.mjs'), `
import { appendFileSync, readFileSync, writeFileSync } from 'node:fs';
export async function shopifyGql(shop, version, token, query, variables) {
  if (shop !== 'fixture.myshopify.com' || token !== 'fixture-token') throw new Error('Attrappe: unerwarteter Shop/Token');
  appendFileSync(process.env.TEST_CALLS, JSON.stringify({query, variables}) + '\\n');
