  if (query.includes('MaterialApiVersion')) return {shop:{url:'https://luxestyle.ch',currencyCode:'CHF'}};
  if (query.includes('MaterialVorher')) return {shop:{url:'https://luxestyle.ch',currencyCode:'CHF'},nodes:variables.ids.map(id=>({id,status:'ACTIVE',m:Object.hasOwn(state,id)?{value:state[id],type:'single_line_text_field',compareDigest:'fixture-'+id+'-'+state[id]}:null}))};
