#!/usr/bin/env node
// Lokale Laufprüfung mit dem echten GraphQL-Helfer und vollständig abgefangenen HTTP-Aufrufen.
import assert from 'node:assert/strict';
import {materialFixtureBelege} from './lib/material_test_fixture.mjs';
import { copyFileSync, existsSync, mkdirSync, mkdtempSync, readFileSync, rmSync, writeFileSync } from 'node:fs';
import { dirname, join, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';
import { spawnSync } from 'node:child_process';

const hier=dirname(fileURLToPath(import.meta.url));
const runner=resolve(process.argv[2] || join(hier,'material_nachtragen.mjs'));
const basis=dirname(runner);
const testBasis=resolve(process.env.MATERIAL_TEST_TMP || join(hier,'.material-batch-fixtures'));
mkdirSync(testBasis,{recursive:true});
let ok=0,fehler=0;

function lauf({anzahl=2,arten=['ok'],vorbelegt=false,fehlerFeld=['metafields','0','value'],lesenFehlt=[],lesenFalsch=[],live=true,limit}={}) {
  const dir=mkdtempSync(join(testBasis,'fall-'));
  try {
    mkdirSync(join(dir,'automation/lib'),{recursive:true}); mkdirSync(join(dir,'dropship')); mkdirSync(join(dir,'cache'));
    copyFileSync(runner,join(dir,'automation/material_nachtragen.mjs'));
    for(const file of ['material.mjs','shopify_gql.mjs','shopify_host.mjs']) copyFileSync(join(basis,'lib',file),join(dir,'automation/lib',file));
    writeFileSync(join(dir,'automation/lib/shopify_secret.mjs'),'export const shopifyClientSecret=()=>"fixture-secret";\n');
    const produkte=Array.from({length:anzahl},(_,i)=>({id:`gid://shopify/Product/${1000+i}`,handle:`fixture-${i}`,title:'Musterbecher',descriptionHtml:'',options:[],m:{value:'Ceramic',type:'single_line_text_field'}}));
    writeFileSync(join(dir,'roh.jsonl'),produkte.map(p=>JSON.stringify(p)).join('\n')+'\n');
    writeFileSync(join(dir,'config.json'),JSON.stringify({arten,fehlerFeld,lesenFehlt,lesenFalsch,vorbelegt}));
    writeFileSync(join(dir,'state.json'),JSON.stringify(Object.fromEntries(produkte.map(p=>[p.id,'Ceramic']))));
    writeFileSync(join(dir,'netz-attrappe.mjs'),`
import { appendFileSync, readFileSync, writeFileSync } from 'node:fs';
const c=JSON.parse(readFileSync(process.env.TEST_CONFIG,'utf8'));
const timer=globalThis.setTimeout;
globalThis.setTimeout=(fn,ms,...args)=>timer(fn,0,...args);
let mutationen=0;
globalThis.fetch=async(url,options)=>{
  if(String(url)==='https://fixture.myshopify.com/admin/oauth/access_token' && options?.method==='POST') return {status:200,json:async()=>({access_token:'fixture-token'})};
  if(String(url)!=='https://fixture.myshopify.com/admin/api/2026-10/graphql.json' || options?.method!=='POST') throw new Error('Testnetz gesperrt');
  const {query,variables}=JSON.parse(options.body);
  appendFileSync(process.env.TEST_CALLS,JSON.stringify({query,variables})+'\\n');
  const state=JSON.parse(readFileSync(process.env.TEST_STATE,'utf8'));
  if(query.includes('MaterialApiVersion')) return {status:200,json:async()=>({data:{shop:{url:'https://luxestyle.ch',currencyCode:'CHF'}}})};
  if(query.includes('MaterialVorher')) return {status:200,json:async()=>({data:{shop:{url:'https://luxestyle.ch',currencyCode:'CHF'},nodes:variables.ids.map(id=>({id,status:'ACTIVE',m:{value:state[id],type:'single_line_text_field',compareDigest:'fixture-'+id+'-'+state[id]}}))}})};
  if(query.includes('metafieldsSet(')) {
    const art=c.arten[Math.min(mutationen++,c.arten.length-1)];
    if(art==='netzfehler') throw new Error('synthetische Verbindungsunterbrechung');
    if(art==='http500') return {status:500,json:async()=>({})};
    if(art==='userErrors') {
      // Ein anderer Schreiber kann nach der Vorabfrage schon passende Werte gesetzt haben; unsere Mutation bleibt abgelehnt.
      if(c.vorbelegt) {for(const m of variables.m) state[m.ownerId]=m.value;writeFileSync(process.env.TEST_STATE,JSON.stringify(state));}
      return {status:200,json:async()=>({data:{metafieldsSet:{metafields:null,userErrors:[{field:c.fehlerFeld,message:'synthetisch abgelehnt',code:'INVALID_VALUE'}]}}})};
    }
    if(art==='null') return {status:200,json:async()=>({data:{metafieldsSet:null}})};
    for(const m of variables.m) state[m.ownerId]=m.value;
    writeFileSync(process.env.TEST_STATE,JSON.stringify(state));
    if(art==='antwort-verloren') throw new Error('synthetisch geschrieben, Antwort verloren');
    let result={metafields:variables.m.map(()=>({key:'material'})),userErrors:[]};
    if(art==='ohne-fehlerliste') delete result.userErrors;
    if(art==='ohne-metafields') result.metafields=null;
    if(art==='zu-kurz') result.metafields.pop();
    if(art==='falscher-key') result.metafields[0].key='color';
    return {status:200,json:async()=>({data:{metafieldsSet:result}})};
  }
  if(query.startsWith('query($id:ID!)')) {
    if(c.lesenFehlt.includes(variables.id)) throw new Error('synthetischer Lesefehler');
    const value=c.lesenFalsch.includes(variables.id)?'abweichend':state[variables.id];
    return {status:200,json:async()=>({data:{product:{m:value===undefined?null:{value,type:'single_line_text_field'}}}})};
  }
  throw new Error('Unerwartete GraphQL-Operation');
};
const fetchAttrappe=globalThis.fetch;
globalThis.fetch=async(...args)=>{const r=await fetchAttrappe(...args);r.headers={get:n=>n.toLowerCase()==='x-shopify-api-version'?'2026-10':null};return r;};
`);
    const env={...materialFixtureBelege(dir),SHOPIFY_SHOP:'fixture.myshopify.com',SHOPIFY_CLIENT_ID:'fixture-client',SHOPIFY_CLIENT_SECRET:'fixture-secret',
      ROH:join(dir,'roh.jsonl'),PLAN:join(dir,'plan.jsonl'),CJ_FAKTEN_CACHE:join(dir,'cache'),TEST_CONFIG:join(dir,'config.json'),TEST_CALLS:join(dir,'calls.jsonl'),TEST_STATE:join(dir,'state.json')};
    if(live) env.LIVE='1'; if(limit!==undefined) env.LIMIT=String(limit);
    const p=spawnSync(process.execPath,['--import',join(dir,'netz-attrappe.mjs'),join(dir,'automation/material_nachtragen.mjs')],{cwd:dir,env,encoding:'utf8',timeout:15000});
    assert.equal(p.error,undefined,p.error?.message);
    const calls=existsSync(env.TEST_CALLS)?readFileSync(env.TEST_CALLS,'utf8').trim().split('\n').filter(Boolean).map(JSON.parse):[];
    const summaries=p.stdout.split('\n').filter(x=>x.startsWith('{')).map(JSON.parse);
    return {status:p.status,stdout:p.stdout,stderr:p.stderr,calls,result:summaries.find(x=>Object.hasOwn(x,'geschrieben')),state:JSON.parse(readFileSync(env.TEST_STATE,'utf8')),ledger:existsSync(join(dir,'dropship/material_ledger.txt'))?readFileSync(join(dir,'dropship/material_ledger.txt'),'utf8'):''};
  } finally {rmSync(dir,{recursive:true,force:true});}
}
function test(name,fn) {try {fn();ok++;console.log('OK '+name);}catch(e){fehler++;console.error('FEHLER '+name+': '+e.message);}}
const mutationen=r=>r.calls.filter(c=>c.query.includes('metafieldsSet('));
const lesungen=r=>r.calls.filter(c=>c.query.startsWith('query($id:ID!)'));
const beleg=r=>{assert.ok(r.result,r.stdout+'\n'+r.stderr);return r.result;};

test('Trockenlauf sendet keine Produktoperation und keinen Erfolgsbeleg',()=>{const r=lauf({live:false});assert.equal(r.status,0);assert.equal(r.calls.length,0);assert.equal(r.ledger,'');});
test('Erfolgreicher Stapel wird vollständig zurückgelesen und bestätigt',()=>{const r=lauf();assert.equal(r.status,0,r.stderr);assert.equal(beleg(r).geschrieben,2);assert.equal(lesungen(r).length,2);assert.match(r.ledger,/2 Produkte/);});
for(const feld of [['metafields','0','value'],['metafields','1','value'],null]) test('Atomarer Fehler verwirft den ganzen Stapel: '+JSON.stringify(feld),()=>{
  const r=lauf({arten:['userErrors'],vorbelegt:true,fehlerFeld:feld});
  if(feld?.[1]==='0') console.log('BELEG atomarer Zweier-Stapel: '+JSON.stringify({exit:r.status,ergebnis:r.result,ledger:r.ledger.trim()}));
  assert.notEqual(r.status,0);assert.equal(beleg(r).geschrieben,0);assert.equal(r.result.fehler,2);assert.equal(mutationen(r).length,1);assert.equal(lesungen(r).length,0);assert.match(r.ledger,/0 Produkte/);
});
test('Definitiver Fehler beendet den Lauf vor späteren Stapeln',()=>{const r=lauf({anzahl:26,arten:['userErrors'],vorbelegt:true});assert.notEqual(r.status,0);assert.equal(mutationen(r).length,1);assert.equal(beleg(r).geschrieben,0);assert.equal(r.result.fehler,25);assert.equal(r.result.nichtBearbeitet,1);});
test('Vorher bestätigter Stapel bleibt bei späterem Fehler korrekt gezählt',()=>{const r=lauf({anzahl:26,arten:['ok','userErrors']});assert.notEqual(r.status,0);assert.equal(beleg(r).geschrieben,25);assert.equal(r.result.fehler,1);assert.equal(lesungen(r).length,25);assert.match(r.ledger,/25 Produkte/);assert.match(r.ledger,/"uebersetzt":25/);});
for(const art of ['null','ohne-fehlerliste','ohne-metafields','zu-kurz','falscher-key']) test('Unklare Antwort zählt keinen Erfolg: '+art,()=>{
  const r=lauf({arten:[art]});assert.notEqual(r.status,0);assert.equal(beleg(r).geschrieben,0);assert.equal(r.result.unbekannt,2);assert.equal(mutationen(r).length,1);assert.equal(lesungen(r).length,0);
});
for(const art of ['netzfehler','http500']) test('Unklarer Transport wird nicht wiederholt: '+art,()=>{
  const r=lauf({arten:[art]});assert.notEqual(r.status,0);assert.equal(mutationen(r).length,1);assert.equal(beleg(r).geschrieben,0);assert.equal(r.result.unbekannt,2);assert.match(r.stderr,/UNBEKANNT/);
});
test('Verlorene Antwort nach ausgeführtem Schreiben bleibt unbekannt ohne Wiederholung',()=>{
  const r=lauf({arten:['antwort-verloren']});assert.notEqual(r.status,0);assert.equal(mutationen(r).length,1);assert.equal(Object.keys(r.state).length,2);assert.equal(beleg(r).geschrieben,0);assert.equal(r.result.unbekannt,2);assert.match(r.stderr,/UNBEKANNT/);
});
test('Alle erfolgreichen IDs werden vor dem nächsten Stapel gelesen',()=>{
  const r=lauf({anzahl:26});assert.equal(r.status,0,r.stderr);assert.equal(beleg(r).geschrieben,26);assert.equal(lesungen(r).length,26);const pos=r.calls.map((c,i)=>c.query.includes('metafieldsSet(')?i:-1).filter(i=>i>=0);assert.equal(pos.length,2);assert.equal(r.calls.slice(pos[0]+1,pos[1]).filter(c=>c.query.startsWith('query($id:ID!)')).length,25);assert.equal(r.result.rueckgelesen,26);
});
test('Abweichende Rücklesung zählt nicht als bestätigtes Schreiben',()=>{
  const r=lauf({lesenFalsch:['gid://shopify/Product/1000']});assert.equal(r.status,3);assert.equal(beleg(r).geschrieben,1);assert.equal(r.result.abweichungen,1);assert.equal(lesungen(r).length,2);assert.match(r.ledger,/1 Produkte/);
});
test('Lesefehler bleibt unbekannt; übrige IDs des Stapels werden dennoch geprüft',()=>{
  const r=lauf({lesenFehlt:['gid://shopify/Product/1000']});assert.notEqual(r.status,0);assert.equal(beleg(r).geschrieben,1);assert.equal(r.result.unbekannt,1);assert.deepEqual([...new Set(lesungen(r).map(c=>c.variables.id))],['gid://shopify/Product/1000','gid://shopify/Product/1001']);assert.equal(mutationen(r).length,1);
});
test('Fehlgeschlagene Gegenprobe verhindert weitere Mutationen',()=>{
