globalThis.setTimeout=(fn,ms,...args)=>timer(fn,0,...args);
const reply=data=>({status:200,headers:{get:n=>n.toLowerCase()==='x-shopify-api-version'?c.header:null},json:async()=>({data})});
globalThis.fetch=async(url,opt)=>{
  if(String(url)==='https://fixture.myshopify.com/admin/oauth/access_token' && opt?.method==='POST') return {status:200,json:async()=>({access_token:'fixture-token'})};
