    for(const m of variables.m) state[m.ownerId]={value:m.value,type:m.type,compareDigest:'digest-danach'};
    writeFileSync(process.env.CAS_STATE,JSON.stringify(state));
    return reply({metafieldsSet:{metafields:variables.m.map(()=>({key:'material'})),userErrors:[]}});
  }
  if(query.startsWith('query($id:ID!)')) return reply({product:{m:state[variables.id]}});
  throw new Error('Unerwartete Operation');
};
`);
    const env={...materialFixtureBelege(dir),SHOPIFY_SHOP:'fixture.myshopify.com',SHOPIFY_CLIENT_ID:'fixture-client',SHOPIFY_CLIENT_SECRET:'fixture-secret',ROH:join(dir,'roh.jsonl'),PLAN:join(dir,'plan.jsonl'),CJ_FAKTEN_CACHE:join(dir,'cache'),CAS_CONFIG:join(dir,'config.json'),CAS_STATE:join(dir,'state.json'),CAS_CALLS:join(dir,'calls.jsonl')};
