test('Sicher fehlendes Feld benutzt explizites null',()=>{const r=lauf({produkt:ohne,frisch:null});assert.equal(r.status,0,r.stderr);const m=mut(r)[0].variables.m[0];assert.ok(Object.hasOwn(m,'compareDigest'));assert.equal(m.compareDigest,null);});
