for(const [name,frisch] of [['geänderter Wert',neu],['gelöschtes Feld',null],['geänderter Typ',{...alt,type:'multi_line_text_field'}],['Leerzeichen im Vorwert',{...alt,value:' Ceramic '}]]) test('Frische Gegenprobe blockiert '+name,()=>{const r=lauf({frisch});block(r);assert.deepEqual(r.state[id],frisch);});
test('Geplante Neuanlage überschreibt keinen inzwischen vorhandenen Wert',()=>{const r=lauf({produkt:ohne,frisch:neu});block(r);assert.deepEqual(r.state[id],neu);});
for(const [name,frisch] of [['fehlender Digest',{value:'Ceramic',type:typ}],['leerer Digest',{...alt,compareDigest:''}],['fehlender Typ',{value:'Ceramic',compareDigest:'a'}],['fehlender Wert',{type:typ,compareDigest:'a'}]]) test('Unbekannte Vorherdaten sperren: '+name,()=>{block(lauf({frisch}));});
test('Alter Rohstand ohne Typ ist keine Schreibfreigabe',()=>{block(lauf({produkt:{...roh,m:{value:'Ceramic'}}}));});
test('Fehlender Roh-Metafeldschlüssel ist nicht sicher abwesend',()=>{const p={...ohne};delete p.m;block(lauf({produkt:p,frisch:null}));});
for(const nodesArt of ['fehlend','null','doppelt','fremd','ohne-m','schemafehler']) test('Unvollständige Vorabantwort sperrt: '+nodesArt,()=>{block(lauf({nodesArt,zwei:nodesArt==='doppelt'}));});
for(const [name,produkt,frisch,race] of [['Update-Race',roh,alt,neu],['Create-Race',ohne,null,neu],['Delete-Race',roh,alt,null],['Typ-Race',roh,alt,{...neu,type:'multi_line_text_field'}]]) test(name+' bleibt atomar abgelehnt',()=>{
  const r=lauf({produkt,frisch,race,zwei:true});assert.notEqual(r.status,0);assert.equal(mut(r).length,1);assert.equal(r.result.geschrieben,0);assert.equal(r.result.fehler,2);assert.deepEqual(r.state[id],race);assert.deepEqual(r.state['gid://shopify/Product/7002'],alt);
});
for(const header of [null,'2026-01']) test('Ungeklärte oder ersetzte API-Version sperrt: '+header,()=>{const r=lauf({header});block(r);assert.match(r.stderr,/API-Version/);});
