test('Auch der Trockenlauf wiederholt einen unklaren Bulk-Start nicht',()=>{const r=lauf({bulk:true,startFehler:'503',live:false});assert.notEqual(r.status,0);assert.equal(start(r).length,1);assert.equal(mut(r).length,0);});
for(const startAntwort of ['keine-fehlerliste','keine-id','fehler'])test('Unvollständiger oder abgelehnter Bulk-Start sperrt: '+startAntwort,()=>{const r=lauf({bulk:true,startAntwort});assert.notEqual(r.status,0);assert.equal(start(r).length,1);assert.equal(mut(r).length,0);assert.equal(r.calls.filter(c=>c.query.includes('bulkOperation(')).length,0);});
test('Paralleler jüngerer Job ersetzt nicht die eigene gestartete Bulk-ID',()=>{const r=lauf({bulk:true,fremderJob:true});assert.equal(r.status,0,r.stderr);assert.equal(start(r).length,1);const polls=r.calls.filter(c=>c.query.includes('bulkOperation('));assert.ok(polls.length>0);assert.ok(polls.every(c=>c.variables.id==='gid://shopify/BulkOperation/801'));assert.ok(mut(r).flatMap(c=>c.variables.m).every(m=>m.ownerId!=='gid://shopify/Product/9999'));assert.equal(r.result.geschrieben,2);});
for(const pollAntwort of ['fehlend','fremde-id','ohne-status','ohne-url'])test('Unbekanntes oder fremdes Bulk-Ergebnis sperrt: '+pollAntwort,()=>{const r=lauf({bulk:true,pollAntwort});assert.notEqual(r.status,0);assert.equal(mut(r).length,0);assert.match(r.stderr,/UNBEKANNT/);});
test('Inflight liegt vor dem Senden vor; bestätigte Werte und Typen stehen danach im Ledger',()=>{const r=lauf();assert.equal(r.status,0,r.stderr);const entries=Object.values(r.ledger.entries);assert.equal(entries.length,1);assert.equal(entries[0].state,'confirmed');assert.equal(entries[0].observation.length,2);assert.ok(entries[0].observation.every(x=>x.value==='Keramik'&&x.type==='single_line_text_field'));});
for(const params of [{shop:'https://andere-marke.ch'},{currency:'USD'},{shop:'https://luxestyle.ch/anderer-pfad'},{productStatus:'DRAFT'},{productStatus:null}])test('Frische Marken-/Statusabweichung sperrt '+JSON.stringify(params),()=>{const r=lauf(params);assert.notEqual(r.status,0);assert.equal(mut(r).length,0);assert.equal(Object.keys(r.ledger.entries).length,0);});
for(const evidenceCase of ['ohne-manifest','keine-policy','alt','zukunft','falscher-hash','produkt-fehlt','cj-geaendert'])test('Unbestätigte echte Eingabebelege sperren: '+evidenceCase,()=>{const r=lauf({evidenceCase});assert.notEqual(r.status,0);assert.equal(mut(r).length,0);assert.equal(Object.keys(r.ledger.entries).length,0);});
for(const ledgerCase of ['fehlend','kaputt','gesperrt'])test('Ungeklärtes Ledger bleibt gesperrt: '+ledgerCase,()=>{const r=lauf({ledgerCase});assert.notEqual(r.status,0);assert.equal(mut(r).length,0);});
test('Unknown bleibt auch im zweiten Prozess ohne erneuten Send',()=>{const r=lauf({writeOutcome:'netz-vor-schreiben',repeat:true});assert.notEqual(r.firstStatus,0);assert.notEqual(r.status,0);assert.equal(mut(r).length,1);assert.equal(r.result.ledgerBlockiert,2);assert.equal(Object.values(r.ledger.entries)[0].state,'unknown');});
test('Trockenlauf ohne Quellenpolicy bleibt möglich und erfindet keine Prüfzeit',()=>{const r=lauf({evidenceCase:'ohne-manifest',live:false});assert.equal(r.status,0,r.stderr);assert.equal(mut(r).length,0);assert.ok(r.plan.every(p=>/^[a-f0-9]{64}$/.test(p.sourceEvidence.sha256)&&p.sourceEvidence.checkedAt===null));assert.equal(Object.keys(r.ledger.entries).length,0);});
for(const params of [{shop:'https://andere-marke.ch'},{shop:'https://andere-marke.ch',live:false},{currency:'USD'}])test('Shop-/CHF-Gegenprobe sperrt bereits vor neuem Bulk-Start '+JSON.stringify(params),()=>{const r=lauf({bulk:true,...params});assert.notEqual(r.status,0);assert.equal(start(r).length,0);assert.equal(mut(r).length,0);});
console.log(`${ok} ok, ${fehler} Fehler`);process.exitCode=fehler?1:0;
